// Extract commits from GitHub push payload
const payload = $input.first().json.body ?? $input.first().json;

const ref = payload.ref ?? '';
const branch = ref.replace('refs/heads/', '');

// Only process pushes to main
if (branch !== 'main') {
  return [];
}

const repo = payload.repository?.full_name ?? 'unknown/repo';
const before = (payload.before ?? '').substring(0, 7);
const after = (payload.after ?? '').substring(0, 7);

const commits = (payload.commits ?? []).map(c => ({
  sha: c.id,
  message: c.message,
  author: c.author?.name ?? c.author?.username ?? 'unknown',
  url: c.url
}));

if (commits.length === 0) {
  return [];
}

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://fyrk-agent-runtime.fly.dev/run/release-notes',
  headers: { 'Content-Type': 'application/json' },
  body: {
    version: '0.1',
    input: {
      mode: 'fixture',
      repo,
      rangeLabel: `${before}..${after}`,
      commits
    },
    dryRun: false,
    publish: true
  },
  json: true,
  timeout: 30000
});

return [{ json: response }];

const data = $input.first().json;
const output = data.output;
const changes = output.changes;

// Skip if only chores (no user-facing changes)
if (changes.features.length === 0 && changes.fixes.length === 0) {
  return [];
}

// Strip conventional commit prefix
function stripPrefix(msg) {
  return msg.replace(/^(feat|fix|chore|docs|refactor|test|style|perf|ci|build)(\([^)]*\))?:\s*/i, '');
}

function capitalize(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

// Generate title from features
const featureTitles = changes.features.map(c => capitalize(stripPrefix(c.message)));
const title = featureTitles.length > 0
  ? featureTitles.slice(0, 2).join(' og ')
  : 'Feilrettinger og forbedringer';

// Generate summary
const parts = [];
if (changes.features.length > 0) parts.push(`${changes.features.length} nye funksjoner`);
if (changes.fixes.length > 0) parts.push(`${changes.fixes.length} feilrettinger`);
if (changes.chores.length > 0) parts.push('generelle forbedringer');
const summary = parts.join(', ') + '.';

// Generate tags
const tags = [];
if (changes.features.length > 0) tags.push('feature');
if (changes.fixes.length > 0) tags.push('fix');
if (changes.chores.length > 0) tags.push('improvement');

// Generate body
const date = output.date;
let body = '## Hva er nytt\n\n';

for (const feat of changes.features) {
  const heading = capitalize(stripPrefix(feat.message));
  body += `### ${heading}\n\n`;
  body += `${heading} er nå tilgjengelig.\n\n`;
}

if (changes.fixes.length > 0) {
  body += '### Feilrettinger\n\n';
  for (const fix of changes.fixes) {
    body += `- ${capitalize(stripPrefix(fix.message))}\n`;
  }
  body += '\n';
}

if (changes.chores.length > 0) {
  body += '### Generelle forbedringer\n\n';
  body += 'Diverse forbedringer og vedlikehold for bedre ytelse og stabilitet.\n';
}

// Sanitize for YAML frontmatter
const safeTitle = title.replace(/"/g, "'");
const safeSummary = summary.replace(/"/g, "'");

// Frontmatter
const frontmatter = `---\ntitle: "${safeTitle}"\ndate: ${date}\nsummary: "${safeSummary}"\ntags: ${JSON.stringify(tags)}\naudience: "user-facing"\ndraft: false\n---`;

const content = frontmatter + '\n\n' + body.trim() + '\n';

// Slug from title
const slug = title
  .toLowerCase()
  .replace(/[æ]/g, 'ae').replace(/[ø]/g, 'o').replace(/[å]/g, 'a')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

const filename = `${date}-${slug}.md`;
const path = `src/content/releaselog/${filename}`;

return [{
  json: {
    path,
    content,
    commitMessage: `docs: releaselog ${date}`,
    date
  }
}];

const data = $input.first().json;
const { path, content, commitMessage } = data;

const encoded = Buffer.from(content).toString('base64');

return [{
  json: {
    apiUrl: `https://api.github.com/repos/carlfrankalbert/nettside_fyrk/contents/${path}`,
    body: {
      message: commitMessage,
      content: encoded,
      committer: {
        name: 'FYRK Agent',
        email: 'agent@fyrk.no'
      }
    },
    path
  }
}];
